CREATE TABLE users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,role TEXT NOT NULL,password_hash TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE projects(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,region TEXT NOT NULL,owner_id TEXT NOT NULL,status TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE plots(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,name TEXT NOT NULL,soil_type TEXT NOT NULL,area_m2 REAL NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,name),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE monitoring_samples(id TEXT PRIMARY KEY,plot_id TEXT NOT NULL,collector_id TEXT NOT NULL,metric TEXT NOT NULL,value TEXT NOT NULL,unit TEXT NOT NULL,collected_at TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(plot_id) REFERENCES plots(id),FOREIGN KEY(collector_id) REFERENCES users(id));
CREATE TABLE remediation_tasks(id TEXT PRIMARY KEY,project_id TEXT NOT NULL,plot_id TEXT NOT NULL,assignee_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL,due_at TEXT,version INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(project_id) REFERENCES projects(id),FOREIGN KEY(plot_id) REFERENCES plots(id),FOREIGN KEY(assignee_id) REFERENCES users(id));
CREATE TABLE task_events(id TEXT PRIMARY KEY,task_id TEXT NOT NULL,actor_id TEXT NOT NULL,from_status TEXT NOT NULL,to_status TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(task_id) REFERENCES remediation_tasks(id),FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE inspections(id TEXT PRIMARY KEY,task_id TEXT NOT NULL,inspector_id TEXT NOT NULL,result TEXT NOT NULL,score INTEGER NOT NULL,notes TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(task_id) REFERENCES remediation_tasks(id),FOREIGN KEY(inspector_id) REFERENCES users(id));
CREATE TABLE audit_logs(id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,request_id TEXT NOT NULL,details TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE idempotency_keys(key TEXT NOT NULL,user_id TEXT NOT NULL,route TEXT NOT NULL,response_code INTEGER NOT NULL,response_body TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(key,user_id,route),FOREIGN KEY(user_id) REFERENCES users(id));
